import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import net from 'node:net';
import os from 'node:os';

const dir = path.resolve(process.argv[2]);
const server = path.join(dir, 'server.mjs');
const results = [];
function check(name, ok, extra = '') { results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : extra}`); }

function runSync(env, cwd) {
  const r = spawnSync('node', [server], { env: { ...process.env, ...env }, cwd, timeout: 3000, encoding: 'utf8' });
  return r;
}

function start(env, cwd) {
  return new Promise((resolve, reject) => {
    const p = spawn('node', [server], { env: { ...process.env, PORT: '0', ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; const m = out.match(/listening on http:\/\/127\.0\.0\.1:(\d+)\n/); if (m) resolve({ p, port: +m[1], getOut: () => out, getErr: () => err }); });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (c) => reject(new Error('exited ' + c + err)));
  });
}

function raw(port, text) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => { buf += d; });
    s.on('end', () => resolve(buf));
    s.on('error', () => resolve(buf));
    s.write(text);
    setTimeout(() => { s.destroy(); resolve(buf); }, 1500);
  });
}

async function req(port, method, p, { body, ct, headers = {} } = {}) {
  const h = { ...headers };
  if (ct !== undefined) h['content-type'] = ct;
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: h, body });
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch {}
  return { status: r.status, ct: r.headers.get('content-type'), text, json };
}

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-'));
const J = 'application/json';
const bk = (o) => JSON.stringify({ room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

// startup checks
for (const [port, expect] of [['abc', 1], ['70000', 1], ['-1', 1], [' 80', 1], ['1e3', 1], ['65536', 1]]) {
  const r = runSync({ PORT: port, DATA_FILE: path.join(tmp, 'x.json') }, tmp);
  check(`PORT=${port} exit1`, r.status === 1 && r.stdout === '' && r.stderr.trim().split('\n').length === 1, JSON.stringify([r.status, r.stdout, r.stderr]));
}
// bad port is checked before data file
{
  fs.writeFileSync(path.join(tmp, 'bad.json'), 'nope');
  const r = runSync({ PORT: 'x', DATA_FILE: 'bad.json' }, tmp);
  check('port checked before data', r.status === 1 && !r.stderr.includes('cannot read'), r.stderr);
}
for (const [content, label] of [['', 'empty'], ['nope', 'invalid'], ['[]', 'array'], ['{}', 'emptyobj'], ['﻿{"nextId":1,"bookings":[]}', 'bom']]) {
  fs.writeFileSync(path.join(tmp, 'bad.json'), content);
  const r = runSync({ PORT: '0', DATA_FILE: 'bad.json' }, tmp);
  check(`datafile ${label}`, r.status === 1 && r.stderr === 'cannot read data file bad.json\n' && r.stdout === '', JSON.stringify([r.status, r.stderr]));
}
fs.mkdirSync(path.join(tmp, 'adir'), { recursive: true });
{
  const r = runSync({ PORT: '0', DATA_FILE: 'adir' }, tmp);
  check('datafile dir', r.status === 1 && r.stderr === 'cannot read data file adir\n', JSON.stringify([r.status, r.stderr]));
}
// in-use port
{
  const blocker = net.createServer().listen(0, '127.0.0.1');
  await new Promise((r) => blocker.on('listening', r));
  const bp = blocker.address().port;
  const r = spawnSync('node', [server], { env: { ...process.env, PORT: String(bp), DATA_FILE: path.join(tmp, 'n.json') }, cwd: tmp, timeout: 3000, encoding: 'utf8' });
  check('port in use exit1', r.status === 1 && r.stdout === '' && r.stderr.trim().split('\n').length === 1, JSON.stringify([r.status, r.stderr]));
  blocker.close();
}

// default DATA_FILE relative to cwd
const cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'cwd-'));
let s = await start({ DATA_FILE: '' }, cwd);
let port = s.port;
let r;
r = await req(port, 'GET', '/api/rooms');
check('rooms', r.status === 200 && JSON.stringify(r.json) === '{"rooms":["Aurora","Borealis","Cosmos"]}' && r.ct === 'application/json; charset=utf-8', r.text);
check('no file at startup', !fs.existsSync(path.join(cwd, 'bookings.json')));
r = await req(port, 'POST', '/api/bookings', { body: bk({ title: '  Standup  ', extra: 1 }), ct: J });
check('create 201', r.status === 201 && JSON.stringify(r.json) === '{"id":1,"room":"Aurora","title":"Standup","date":"2026-11-03","start":"09:00","end":"10:00"}', r.text);
check('file in cwd', fs.existsSync(path.join(cwd, 'bookings.json')));
r = await req(port, 'POST', '/api/bookings', { body: bk({ start: '09:30', end: '11:00' }), ct: J });
check('409', r.status === 409 && r.json?.error === 'room is already booked from 09:00 to 10:00', r.text);
r = await req(port, 'POST', '/api/bookings', { body: bk({ start: '10:00', end: '11:00' }), ct: J });
check('adjacent ok', r.status === 201 && r.json.id === 2, r.text);
r = await req(port, 'POST', '/api/bookings', { body: bk({ start: '08:00', end: '12:00' }), ct: J });
check('409 earliest', r.status === 409 && r.json?.error === 'room is already booked from 09:00 to 10:00', r.text);
r = await req(port, 'POST', '/api/bookings', { body: bk({ room: 'Cosmos', start: '09:00', end: '09:30' }), ct: J });
r = await req(port, 'POST', '/api/bookings', { body: bk({ room: 'Borealis', start: '09:00', end: '09:30', date: '2026-11-02' }), ct: J });
r = await req(port, 'GET', '/api/bookings');
check('sorted', r.status === 200 && r.json.bookings.map((b) => b.id).join(',') === '4,1,3,2', r.text);
r = await req(port, 'GET', '/api/bookings?date=2026-11-02&date=x');
check('filter first', r.status === 200 && r.json.bookings.length === 1, r.text);
r = await req(port, 'GET', '/api/bookings?date');
check('?date empty 400', r.status === 400 && r.json.error === 'date must be a valid YYYY-MM-DD date', r.text);
r = await req(port, 'GET', '/api/bookings?dat%65=2026-11-02');
