import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import net from 'node:net';
import os from 'node:os';

const dir = path.resolve(process.argv[2]);
const server = path.join(dir, 'server.mjs');
const results = [];
function check(name, ok, extra = '') { results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : extra}`); }

function runSync(env, cwd) {
  const r = spawnSync('node', [server], { env: { ...process.env, ...env }, cwd, timeout: 3000, encoding: 'utf8' });
  return r;
}

function start(env, cwd) {
  return new Promise((resolve, reject) => {
    const p = spawn('node', [server], { env: { ...process.env, PORT: '0', ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; const m = out.match(/listening on http:\/\/127\.0\.0\.1:(\d+)\n/); if (m) resolve({ p, port: +m[1], getOut: () => out, getErr: () => err }); });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (c) => reject(new Error('exited ' + c + err)));
  });
}

function raw(port, text) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => { buf += d; });
    s.on('end', () => resolve(buf));
    s.on('error', () => resolve(buf));
    s.write(text);
    setTimeout(() => { s.destroy(); resolve(buf); }, 1500);
  });
}

async function req(port, method, p, { body, ct, headers = {} } = {}) {
  const h = { ...headers };
  if (ct !== undefined) h['content-type'] = ct;
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: h, body });
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch {}
  return { status: r.status, ct: r.headers.get('content-type'), text, json };
}

