const ysrc = fs.readFileSync(root + "Y/server.mjs", "utf8"); const m = ysrc.match(/const SCRIPT = `([\s\S]*?)`;\n/);
const srcs = { W: fs.readFileSync(root + code.W, "utf8"), X: fs.readFileSync(root + code.X, "utf8"), Y: m[1].replace(/\\\\/g, "\\"), Z: fs.readFileSync(root + code.Z, "utf8") };
class El { constructor(tag, id) { this.tagName = tag; this.id = id; this.children = []; this.listeners = {}; this.value = ""; this.disabled = false; this._text = ""; this.type = ""; }
  get textContent() { return this.children.length ? this.children.map((c) => typeof c === "string" ? c : c.textContent).join("") : this._text; }
  set textContent(v) { this._text = String(v); this.children = []; }
  append(...n) { this.children.push(...n.map((x) => typeof x === "string" ? x : x)); }
  replaceChildren(...n) { this.children = n; }
  addEventListener(t, f) { (this.listeners[t] ||= []).push(f); }
  fire(t, ev = {}) { for (const f of this.listeners[t] || []) f({ preventDefault() { ev.prevented = true; }, ...ev }); return ev; } }
function setup(src) {
  const ids = ["booking-form","room","title","date","start","end","book","filter-date","show-all","booking-list","error"];
  const els = Object.fromEntries(ids.map((i) => [i, new El("x", i)]));
  const calls = [];
  const fetch = (url, opts) => new Promise((resolve, reject) => { calls.push({ url, opts, resolve, reject }); });
  const document = { getElementById: (i) => els[i], createElement: (t) => new El(t) };
  vm.runInNewContext(src, { document, fetch, console });
  return { els, calls };
}
const reply = (status, body, bad) => ({ status, json: () => bad ? Promise.reject(new Error("x")) : Promise.resolve(body) });
const tick = () => new Promise((r) => setTimeout(r, 5));
const liText = (els) => els["booking-list"].children.map((li) => li.children.map((c) => typeof c === "string" ? JSON.stringify(c) : c.tagName + ":" + c.type + ":" + c.textContent).join("+"));
