  // overlapping list fetches
  els["filter-date"].value = "2026-11-03"; els["filter-date"].fire("input");
  check("input does nothing", calls.length === 2);
  els["filter-date"].fire("change"); els["show-all"].fire("click");
  check("filter urls", calls[2].url === "/api/bookings?date=2026-11-03" && calls[3].url === "/api/bookings" && els["filter-date"].value === "" && calls.length === 4, calls.slice(2).map((c) => c.url).join());
  calls[3].resolve(reply(200, { bookings: [] })); await tick();
  calls[2].reject(new Error("down")); await tick();
  check("stale ignored", els.error.textContent === "" && JSON.stringify(liText(els)) === "[\"\\\"No bookings.\\\"\"]", els.error.textContent + JSON.stringify(liText(els)));
  // submit
  els.title.value = " Hi "; els.date.value = "2026-11-03"; els.start.value = "09:00"; els.end.value = "10:00"; els.room.value = "Aurora";
  let ev = els["booking-form"].fire("submit", {});
  check("prevented", ev.prevented === true);
  check("disabled", els.book.disabled === true && calls.length === 5 && calls[4].opts.method === "POST" && JSON.stringify(calls[4].opts.headers) === "{\"Content-Type\":\"application/json\"}" && calls[4].opts.body === JSON.stringify({ room: "Aurora", title: " Hi ", date: "2026-11-03", start: "09:00", end: "10:00" }), JSON.stringify(calls[4]?.opts));
  els["booking-form"].fire("submit", {}); check("no double submit", calls.length === 5);
