  check("409 shown", els.error.textContent === "room is already booked from 09:00 to 10:00" && !els.book.disabled && els.title.value === " Hi " && calls.length === 5);
  els["booking-form"].fire("submit", {}); calls[5].resolve(reply(500, "nope")); await tick();
  check("non-object body", els.error.textContent === "Request failed.", els.error.textContent);
  els["booking-form"].fire("submit", {}); calls[6].resolve(reply(500, null, true)); await tick();
  check("unparseable = no reply", els.error.textContent === "Could not reach the server." && !els.book.disabled, els.error.textContent);
  els["booking-form"].fire("submit", {}); calls[7].resolve(reply(200, {})); await tick();
  check("200 on POST is error", els.error.textContent === "Request failed." && calls.length === 8, els.error.textContent);
